# Pokemon Battle

A simple Expo Go battle simulator using live PokeAPI data.

- Follow the course examples. Keep functions and comments short and clear.
- Build only setup, the fight and history. No bonus features.
- Screens in `src/app/`, reusable UI in `src/components/`, hooks in `src/hooks/`, API and SQL in `src/services/`, battle rules in `src/utils/`.
- Screens do not fetch data or run SQL. Use TanStack Query hooks.
- One QueryClient in `src/app/_layout.tsx`. One database in `src/services/history-db.ts`.
- All colours, spacing and radii are in `src/constants/theme.ts`.
- Use React Native components, StyleSheet, Pressable and FlatList.
- Show loading and error states, including failed saving and sharing.
- Use Expo SDK 58 to match the user's iPhone Expo Go. The course starter uses SDK 57; keep its simple coding patterns. Install native packages with `npx expo install` and check the versioned Expo docs.
- Run lint, typecheck and battle rule tests after changing battle logic.
- Do not edit the course material outside this app.
- Once the student's own GitHub repository is available, use one issue per feature, post the plan and checklist on it, and wait for the user's go before each new issue. The current local base build was explicitly requested in this chat.
import { router } from 'expo-router';
import { useState } from 'react';
import { FlatList, Pressable, StyleSheet, Text, TextInput, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { Button } from '@/components/button';
import { LoadState } from '@/components/load-state';
import { PokemonCard } from '@/components/pokemon-card';
import { Colors, Radius, Spacing } from '@/constants/theme';
import { usePokemon, usePokemonList } from '@/hooks/use-pokemon';

export default function SetupScreen() {
  const [query, setQuery] = useState('');
  const [target, setTarget] = useState<'player' | 'opponent'>('player');
  const [playerId, setPlayerId] = useState('');
  const [opponentId, setOpponentId] = useState('');
  const list = usePokemonList();
  const player = usePokemon(playerId);
  const opponent = usePokemon(opponentId);
  const pokemon = list.data?.filter((entry) => entry.name.includes(query.trim().toLowerCase())) ?? [];

  function select(id: number) {
    if (target === 'player') {
      setPlayerId(String(id));
      setTarget('opponent');
    } else setOpponentId(String(id));
  }

  return (
    <SafeAreaView edges={['bottom', 'left', 'right']} style={styles.screen}>
      <FlatList
        data={pokemon}
        keyboardShouldPersistTaps="handled"
        keyExtractor={(item) => String(item.id)}
        contentContainerStyle={styles.content}
        ListHeaderComponent={
          <View style={styles.header}>
            <Text style={styles.title}>Choose your fighters</Text>
            <Text style={styles.text}>Both fight at level 50 using their API base stats.</Text>
            <View style={styles.row}>
              <View style={styles.selection}>
                <Button title="Your Pokemon" secondary={target !== 'player'} onPress={() => setTarget('player')} />
                {player.data ? <PokemonCard pokemon={player.data} label="You" /> : playerId ? (
                  <LoadState message={player.isError ? 'Could not load your Pokemon.' : 'Loading Pokemon...'} error={player.isError} onRetry={() => player.refetch()} />
                ) : <Text style={styles.hint}>Select from the list below.</Text>}
              </View>
              <View style={styles.selection}>
                <Button title="Opponent" secondary={target !== 'opponent'} onPress={() => setTarget('opponent')} />
                {opponent.data ? <PokemonCard pokemon={opponent.data} label="Opponent" /> : opponentId ? (
                  <LoadState message={opponent.isError ? 'Could not load opponent.' : 'Loading Pokemon...'} error={opponent.isError} onRetry={() => opponent.refetch()} />
                ) : <Text style={styles.hint}>Select from the list below.</Text>}
              </View>
            </View>
            <Button
              title="Start battle"
