export type PokemonName = { id: number; name: string };

export type Pokemon = PokemonName & {
  image: string | null;
  types: string[];
  moves: string[];
  hp: number;
  attack: number;
  defense: number;
  specialAttack: number;
  specialDefense: number;
  speed: number;
};

export type Move = {
  id: number;
  name: string;
  power: number | null;
  accuracy: number | null;
  type: string;
  damageClass: string;
};

export type TypeRelations = {
  noDamage: string[];
  halfDamage: string[];
  doubleDamage: string[];
};

export type Fighter = { pokemon: Pokemon; moves: Move[] };

export type BattleData = {
  player: Fighter;
  opponent: Fighter;
  struggle: Move;
  relations: Record<string, TypeRelations>;
};

export type BattleState = {
  playerHp: number;
  opponentHp: number;
  turns: number;
  log: string[];
  winner: 'player' | 'opponent' | 'draw' | null;
};

export type BattleResult = {
  id: string;
  player: string;
  opponent: string;
  winner: string;
  turns: number;
};

export type HistoryRow = BattleResult & { created_at: string };
import type { BattleData, Move, Pokemon, PokemonName, TypeRelations } from '@/types';

const baseUrl = 'https://pokeapi.co/api/v2';

export function pokemonSprite(id: number): string {
  return `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${id}.png`;
}

type NamedResource = { name: string; url: string };
type PokemonResponse = {
  id: number;
  name: string;
  sprites: {
    front_default: string | null;
    other: { 'official-artwork': { front_default: string | null } };
  };
  types: { type: NamedResource }[];
  moves: { move: NamedResource }[];
  stats: { base_stat: number; stat: NamedResource }[];
};
type MoveResponse = {
  id: number;
  name: string;
  power: number | null;
  accuracy: number | null;
  type: NamedResource;
  damage_class: NamedResource;
};
type TypeResponse = {
  damage_relations: {
    no_damage_to: NamedResource[];
    half_damage_to: NamedResource[];
    double_damage_to: NamedResource[];
  };
};

async function getJson<T>(path: string): Promise<T> {
  const response = await fetch(`${baseUrl}/${path}`);
  if (!response.ok) throw new Error('Could not load PokeAPI data. Please try again.');
  return response.json();
}

export async function getPokemonList(): Promise<PokemonName[]> {
  const data = await getJson<{ results: NamedResource[] }>('pokemon?limit=100000');
  return data.results.map((pokemon) => ({
    id: Number(pokemon.url.split('/').filter(Boolean).pop()),
    name: pokemon.name,
  }));
}

export async function getPokemon(id: string): Promise<Pokemon> {
  const data = await getJson<PokemonResponse>(`pokemon/${id}`);
  function stat(name: string) {
    const value = data.stats.find((entry) => entry.stat.name === name);
    if (!value) throw new Error(`Missing Pokemon stat: ${name}`);
    return value.base_stat;
  }
  return {
    id: data.id,
    name: data.name,
    image: data.sprites.other['official-artwork'].front_default ?? data.sprites.front_default,
    types: data.types.map((entry) => entry.type.name),
    moves: data.moves.slice(0, 4).map((entry) => entry.move.name),
    hp: stat('hp'),
    attack: stat('attack'),
    defense: stat('defense'),
    specialAttack: stat('special-attack'),
    specialDefense: stat('special-defense'),
    speed: stat('speed'),
  };
}

async function getMove(name: string): Promise<Move> {
  const data = await getJson<MoveResponse>(`move/${name}`);
  return {
    id: data.id,
    name: data.name,
    power: data.power,
    accuracy: data.accuracy,
    type: data.type.name,
    damageClass: data.damage_class.name,
  };
}

async function getType(name: string): Promise<TypeRelations> {
  const { damage_relations: relations } = await getJson<TypeResponse>(`type/${name}`);
  return {
    noDamage: relations.no_damage_to.map((type) => type.name),
    halfDamage: relations.half_damage_to.map((type) => type.name),
    doubleDamage: relations.double_damage_to.map((type) => type.name),
  };
}

export async function getBattleData(player: Pokemon, opponent: Pokemon): Promise<BattleData> {
  const names = [...new Set([...player.moves, ...opponent.moves, 'struggle'])];
  const moves = await Promise.all(names.map(getMove));
  function findMove(name: string) {
    const move = moves.find((entry) => entry.name === name);
    if (!move) throw new Error('Could not load a move. Please try again.');
    return move;
  }
  const types = [...new Set(moves.map((move) => move.type))];
  const relations: Record<string, TypeRelations> = {};
  await Promise.all(types.map(async (type) => { relations[type] = await getType(type); }));
  const struggle = findMove('struggle');
  return {
    player: { pokemon: player, moves: player.moves.length ? player.moves.map(findMove) : [struggle] },
    opponent: { pokemon: opponent, moves: opponent.moves.length ? opponent.moves.map(findMove) : [struggle] },
    struggle,
    relations,
  };
}
import { useQuery } from '@tanstack/react-query';

import { getBattleData, getPokemon, getPokemonList } from '@/services/pokeapi';
import type { Pokemon } from '@/types';

const staleTime = 60 * 60 * 1000;

export function usePokemonList() {
  return useQuery({ queryKey: ['pokemon', 'list'], queryFn: getPokemonList, staleTime });
}

export function usePokemon(id: string) {
  return useQuery({
    queryKey: ['pokemon', id],
    queryFn: () => getPokemon(id),
    enabled: id.length > 0,
    staleTime,
  });
}

export function useBattleData(player?: Pokemon, opponent?: Pokemon) {
  return useQuery({
    queryKey: ['battle-data', player?.id, opponent?.id],
    queryFn: () => {
      if (!player || !opponent) throw new Error('Choose two Pokemon first.');
      return getBattleData(player, opponent);
    },
    enabled: !!player && !!opponent,
    staleTime,
  });
}
import { useRef, useState } from 'react';

import { useSaveBattle } from '@/hooks/use-history';
import type { BattleData, BattleResult, Move } from '@/types';
import { createBattle, playTurn } from '@/utils/battle';

export function useBattle(data: BattleData) {
  const [state, setState] = useState(() => createBattle(data));
  // Keep quick taps on the latest turn.
  const current = useRef(state);
  const [id] = useState(() => `${Date.now()}-${Math.random().toString(36).slice(2)}`);
  const [result, setResult] = useState<BattleResult | null>(null);
  const save = useSaveBattle();

  function chooseMove(move: Move) {
    if (current.current.winner) return;
    const next = playTurn(current.current, data, move);
    current.current = next;
    setState(next);
    if (next.winner) {
      const finished = {
        id,
        player: data.player.pokemon.name,
        opponent: data.opponent.pokemon.name,
        winner: next.winner === 'draw' ? 'Draw' : next.winner === 'player' ? data.player.pokemon.name : data.opponent.pokemon.name,
        turns: next.turns,
      };
      setResult(finished);
      save.mutate(finished);
    }
  }

  return { state, result, chooseMove, save };
}
import type { BattleData, BattleState, Move, Pokemon, TypeRelations } from '../types';

export function getEffectiveness(defenderTypes: string[], relations: TypeRelations): number {
  return defenderTypes.reduce((multiplier, type) => {
    if (relations.noDamage.includes(type)) return 0;
    if (relations.doubleDamage.includes(type)) return multiplier * 2;
    if (relations.halfDamage.includes(type)) return multiplier * 0.5;
    return multiplier;
  }, 1);
}

export function calculateDamage(
  attacker: Pokemon,
  defender: Pokemon,
  move: Move,
  effectiveness: number,
  random = Math.random,
): number {
  if (effectiveness === 0) return 0;
  const special = move.damageClass === 'special';
  const attack = special ? attacker.specialAttack : attacker.attack;
  const defense = special ? defender.specialDefense : defender.defense;
  const level = 50;
  const base = Math.floor(Math.floor((Math.floor(2 * level / 5) + 2) * (move.power ?? 0) * attack / defense) / 50) + 2;
  const roll = (85 + Math.floor(random() * 16)) / 100;
  const stab = move.name !== 'struggle' && attacker.types.includes(move.type) ? 1.5 : 1;
  const rolled = Math.floor(base * roll);
  const withStab = Math.ceil(rolled * stab - 0.5);
  return Math.max(1, Math.floor(withStab * effectiveness));
}

export function createBattle(data: BattleData): BattleState {
  return {
    playerHp: data.player.pokemon.hp,
    opponentHp: data.opponent.pokemon.hp,
    turns: 0,
    log: ['Choose a move to begin.'],
    winner: null,
  };
}

export function playTurn(
  state: BattleState,
  data: BattleData,
  chosenMove: Move,
  random = Math.random,
): BattleState {
  if (state.winner) return state;
  const player = data.player.pokemon;
  const opponent = data.opponent.pokemon;
  const opponentMove = data.opponent.moves[Math.floor(random() * data.opponent.moves.length)];
  const playerFirst = player.speed === opponent.speed ? random() < 0.5 : player.speed > opponent.speed;
  let playerHp = state.playerHp;
  let opponentHp = state.opponentHp;
  const messages = [`Turn ${state.turns + 1}`];

  function attack(isPlayer: boolean) {
    const attacker = isPlayer ? player : opponent;
    const defender = isPlayer ? opponent : player;
    const selected = isPlayer ? chosenMove : opponentMove;
    const move = selected.power && selected.power > 0 ? selected : data.struggle;
    const label = isPlayer ? 'Your' : 'Opponent';
    if (move !== selected) messages.push(`${selected.name} has no power. Using Struggle.`);
    if (move.name !== 'struggle' && move.accuracy !== null && random() * 100 >= move.accuracy) {
      messages.push(`${label} ${attacker.name} used ${move.name}: miss.`);
      return;
    }
    const effectiveness = move.name === 'struggle' ? 1 : getEffectiveness(defender.types, data.relations[move.type]);
    const damage = calculateDamage(attacker, defender, move, effectiveness, random);
    const lostHp = Math.min(damage, isPlayer ? opponentHp : playerHp);
    if (isPlayer) opponentHp -= lostHp;
    else playerHp -= lostHp;
    messages.push(`${label} ${attacker.name} used ${move.name}: hit for ${lostHp} HP.`);
    if (effectiveness === 0) messages.push('No effect.');
    else if (effectiveness > 1) messages.push('Super effective!');
    else if (effectiveness < 1) messages.push('Not very effective.');
    if (move.name === 'struggle') {
      const recoil = Math.max(1, Math.round(attacker.hp / 4));
      if (isPlayer) playerHp = Math.max(0, playerHp - recoil);
      else opponentHp = Math.max(0, opponentHp - recoil);
      messages.push(`${label} ${attacker.name} took ${recoil} HP recoil.`);
    }
  }

  attack(playerFirst);
  if (playerHp > 0 && opponentHp > 0) attack(!playerFirst);
  let winner: BattleState['winner'] = null;
  if (playerHp === 0 && opponentHp === 0) winner = 'draw';
  else if (opponentHp === 0) winner = 'player';
  else if (playerHp === 0) winner = 'opponent';
  if (winner) {
    messages.push(winner === 'draw' ? 'Both Pokemon fainted. Draw.' : `${winner === 'player' ? 'Your' : 'Opponent'} Pokemon wins!`);
  }
  return { playerHp, opponentHp, turns: state.turns + 1, log: [...messages, ...state.log], winner };
}
