              <PokemonCard pokemon={data.opponent.pokemon} label="Opponent" hp={state.opponentHp} />
            </View>
            <Text style={styles.title}>{state.winner ? winner : 'Choose your move'}</Text>
            {!state.winner && data.player.moves.map((move) => (
              <Button
                key={move.id}
                title={`${move.name.replaceAll('-', ' ')} · ${move.power ? `${move.type}, power ${move.power}, ${move.accuracy === null ? 'always hits' : `${move.accuracy}% accuracy`}` : 'uses Struggle'}`}
                onPress={() => chooseMove(move)}
              />
            ))}
            {!state.winner && <Text style={styles.text}>Faster Pokemon attacks first. Opponent chooses randomly.</Text>}
            {result && (
              <>
                <Text style={styles.text}>Finished in {result.turns} turns.</Text>
                {save.isPending && <LoadState message="Saving result..." />}
                {save.isError && <LoadState message="Result could not be saved." error onRetry={() => save.mutate(result)} />}
