import { useEffect, useRef, useState } from 'react';

import { useSaveBattle } from '@/hooks/use-history';
import type { BattleAction, BattleData, BattleResult, Move } from '@/types';
import { createBattle, playTurn } from '@/utils/battle';

const pause = (milliseconds: number) => new Promise<void>((resolve) => setTimeout(resolve, milliseconds));

export function useBattle(data: BattleData) {
  const [state, setState] = useState(() => createBattle(data));
  // Keep quick taps on the latest turn.
  const current = useRef(state);
  const playing = useRef(false);
  const mounted = useRef(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [action, setAction] = useState<BattleAction | null>(null);
  const [message, setMessage] = useState('Choose a move to begin.');
  const [id] = useState(() => `${Date.now()}-${Math.random().toString(36).slice(2)}`);
  const [result, setResult] = useState<BattleResult | null>(null);
  const save = useSaveBattle();

  useEffect(() => {
    mounted.current = true;
    return () => { mounted.current = false; };
  }, []);

  async function chooseMove(move: Move) {
    if (playing.current || current.current.winner) return;
    playing.current = true;
    setIsPlaying(true);
    try {
      const next = playTurn(current.current, data, move);
      setState((previous) => ({ ...previous, turns: next.turns, log: [`Turn ${next.turns}`, ...previous.log] }));
      for (const step of next.steps) {
        const attacker = step.attacker === 'player' ? 'Your' : 'Opponent';
        const name = data[step.attacker].pokemon.name;
        setMessage(`${attacker} ${name} used ${step.move.replaceAll('-', ' ')}!`);
        setAction({ step, phase: 'attack' });
        await pause(500);
        if (!mounted.current) return;
        setState((previous) => ({ ...previous,
          playerHp: step.playerHp, opponentHp: step.opponentHp,
          log: [...step.messages, ...previous.log],
        }));
        setMessage(step.messages.join('\n'));
        setAction({ step, phase: 'damage' });
        await pause(1200);
        if (!mounted.current) return;
        if (step.playerHp === 0 || step.opponentHp === 0) {
          setAction({ step, phase: 'faint' });
          setMessage(step.playerHp === 0 && step.opponentHp === 0 ? 'Both Pokemon fainted.'
            : step.playerHp === 0 ? 'Your Pokemon fainted.' : 'Opponent Pokemon fainted.');
          await pause(700);
          if (!mounted.current) return;
        }
      }
      current.current = next;
      setState(next);
      setAction(null);
      setMessage(next.winner ? 'Battle finished.' : 'Choose your next move.');
      if (next.winner) {
        const finished = {
          id,
          player: data.player.pokemon.name,
          opponent: data.opponent.pokemon.name,
          winner: next.winner === 'draw' ? 'Draw' : next.winner === 'player' ? data.player.pokemon.name : data.opponent.pokemon.name,
          turns: next.turns,
        };
        setResult(finished);
        save.mutate(finished);
      }
    } finally {
      playing.current = false;
      if (mounted.current) setIsPlaying(false);
    }
  }

  return { state, result, chooseMove, save, action, message, isPlaying };
}
import { router, useLocalSearchParams } from 'expo-router';
import { useState } from 'react';
import { FlatList, Pressable, StyleSheet, Text, TextInput, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { Button } from '@/components/button';
import { LoadState } from '@/components/load-state';
import { MoveRow } from '@/components/move-row';
import { Colors, Radius, Spacing } from '@/constants/theme';
import { usePokemon } from '@/hooks/use-pokemon';
import type { Pokemon } from '@/types';

export default function MovesScreen() {
  const params = useLocalSearchParams<{ player?: string; opponent?: string }>();
  const player = usePokemon(params.player ?? '');
  if (!params.player || !params.opponent) {
    return <Button title="Choose two Pokemon" onPress={() => router.replace('/')} />;
  }
  if (!player.data) {
    return <LoadState message={player.isError ? 'Could not load moves.' : 'Loading Pokemon...'} error={player.isError} onRetry={() => player.refetch()} />;
  }
  return <MoveSelection key={player.data.id} pokemon={player.data} opponentId={params.opponent} />;
}

function MoveSelection({ pokemon, opponentId }: { pokemon: Pokemon; opponentId: string }) {
  const [selected, setSelected] = useState(pokemon.moves.slice(0, 4));
  const [query, setQuery] = useState('');
  const limit = Math.min(4, pokemon.moves.length);
  const moves = pokemon.moves.filter((name) => name.includes(query.trim().toLowerCase().replaceAll(' ', '-')));

  function toggle(name: string) {
    setSelected((previous) => previous.includes(name) ? previous.filter((move) => move !== name)
      : previous.length < limit ? [...previous, name] : previous);
  }

  return (
    <SafeAreaView edges={['bottom', 'left', 'right']} style={styles.screen}>
      <View style={styles.header}>
        <Text style={styles.title}>{`${pokemon.name.replaceAll('-', ' ')}'s moves`}</Text>
        <Text style={styles.text}>Tap a selected move to free a slot, then choose a replacement. Moves without power use Struggle.</Text>
        <Text style={styles.count}>{selected.length} / {limit} selected</Text>
        <View style={styles.selected}>
          {selected.map((name) => (
            <Pressable key={name} accessibilityRole="button" accessibilityLabel={`Remove ${name}`} onPress={() => toggle(name)} style={styles.chip}>
              <Text style={styles.chipText}>{name.replaceAll('-', ' ')} ×</Text>
            </Pressable>
          ))}
        </View>
        <Button title="Start battle" disabled={selected.length !== limit} onPress={() => router.push({
          pathname: '/battle', params: { player: String(pokemon.id), opponent: opponentId, moves: selected.join(',') },
        })} />
        <TextInput
          style={styles.search} value={query} onChangeText={setQuery}
          placeholder="Search moves" placeholderTextColor={Colors.muted}
          accessibilityLabel="Search moves" autoCapitalize="none" autoCorrect={false} clearButtonMode="while-editing"
        />
      </View>
      <FlatList
        data={moves} keyExtractor={(name) => name}
        contentContainerStyle={styles.list}
        keyboardShouldPersistTaps="handled" keyboardDismissMode="on-drag" automaticallyAdjustKeyboardInsets
        initialNumToRender={8} maxToRenderPerBatch={8} windowSize={3}
        renderItem={({ item }) => <MoveRow name={item} selected={selected.includes(item)} disabled={!selected.includes(item) && selected.length === limit} onPress={() => toggle(item)} />}
        ListEmptyComponent={<Text style={styles.text}>No moves found.</Text>}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1 },
  header: { padding: Spacing.three, gap: Spacing.two },
  title: { fontSize: 22, fontWeight: '700', color: Colors.text, textTransform: 'capitalize' },
